/**
 * The file token cap (the register's row of 2026-10-22 on the file token
 * cap; J-114 S4): an authored file over a cap of tokens, counted as its bytes
 * over four, is refused with how to split it, by `greenline check files
 * --max-tokens <n>` as a declared check, never a git hook. The manifest's
 * `fileTokens` opts a workspace in, with 5,000 tokens as the default cap and
 * its own exemptions beside the standard ones: lockfiles, generated files,
 * vendored trees and data. Pure: the shell lists and reads the files.
 */

/** The cap a workspace takes where its manifest's `fileTokens` names none. */
export const DEFAULT_FILE_TOKENS = 5000;

/** The tokens a file of so many bytes counts, its bytes over four, rounded up. */
export function tokensOf(bytes: number): number {
  return Math.ceil(bytes / 4);
}

/** The exemptions every workspace takes, each with the kind of file it names. */
const STANDARD_EXEMPTIONS: readonly { readonly glob: string; readonly kind: string }[] = [
  ...[
    "pnpm-lock.yaml",
    "package-lock.json",
    "npm-shrinkwrap.json",
    "yarn.lock",
    "bun.lock",
    "bun.lockb",
    "Cargo.lock",
    "Gemfile.lock",
    "poetry.lock",
    "Pipfile.lock",
    "uv.lock",
    "composer.lock",
    "go.sum",
    "flake.lock",
    "mix.lock",
    "Podfile.lock",
    "packages.lock.json",
    "gradle.lockfile",
  ].map((glob) => ({ glob, kind: "a lockfile" })),
  ...[
    "*.min.js",
    "*.min.css",
    "*.map",
    "*.snap",
    "*.generated.*",
    "dist/**",
    "build/**",
    "out/**",
    "coverage/**",
    ".greenline/**",
    ".claude/skills/**",
    ".agents/skills/**",
    "AGENTS.md",
    "CLAUDE.md",
  ].map((glob) => ({ glob, kind: "a generated file" })),
  ...["vendor/**", "node_modules/**", "third_party/**", "third-party/**", ".yarn/**"].map(
    (glob) => ({ glob, kind: "a vendored tree" }),
  ),
  ...[
    "*.csv",
    "*.tsv",
    "*.jsonl",
    "*.ndjson",
    "*.parquet",
    "*.sqlite",
    "*.db",
    "*.svg",
    "*.png",
    "*.jpg",
    "*.jpeg",
    "*.gif",
    "*.webp",
    "*.ico",
    "*.pdf",
    "*.woff",
    "*.woff2",
    "*.ttf",
    "*.otf",
    "*.zip",
    "*.gz",
    "*.tar",
    "*.wasm",
  ].map((glob) => ({ glob, kind: "data" })),
];

/**
 * A glob as a regular expression over a path from the root, `/`-separated:
 * `**` any run of folders, `*` any name or part of one, `?` one character; a
 * glob with no slash matches the file's name in any folder.
 * @param glob the glob
 * @returns the expression
 */
function globExpression(glob: string): RegExp {
  let out = "";
  for (let index = 0; index < glob.length; index += 1) {
    const char = glob[index] ?? "";
    if (char === "*" && glob[index + 1] === "*") {
      const slash = glob[index + 2] === "/";
      out += slash ? "(?:.*/)?" : ".*";
      index += slash ? 2 : 1;
    } else if (char === "*") out += "[^/]*";
    else if (char === "?") out += "[^/]";
    else out += char.replace(/[.+^${}()|[\]\\]/g, "\\$&");
  }
  return new RegExp(glob.includes("/") ? `^${out}$` : `(?:^|/)${out}$`);
}

/** A file's exemption: the glob that names it and the kind of file it is. */
export interface Exemption {
  readonly glob: string;
  readonly kind: string;
}

/**
 * The exemption a path takes, the workspace's own first, else the standard
 * ones, or undefined when none names it.
 * @param path the path from the root, `/`-separated
 * @param own the manifest's `fileTokens.exempt` globs
 * @returns the exemption, or undefined
 */
export function exemptionOf(path: string, own: readonly string[]): Exemption | undefined {
  const workspace = own.find((glob) => globExpression(glob).test(path));
  if (workspace !== undefined) return { glob: workspace, kind: "the manifest's exemption" };
  return STANDARD_EXEMPTIONS.find((entry) => globExpression(entry.glob).test(path));
}

/**
 * Whether a file's opening says it is generated, as generators mark their
 * output: `@generated`, `DO NOT EDIT` or `auto-generated` in its first lines.
 * @param head the file's first bytes as text
 * @returns true for a generated file
 */
export function markedGenerated(head: string): boolean {
  return /@generated|DO NOT EDIT|auto-generated|autogenerated/i.test(
    head.split("\n").slice(0, 5).join("\n"),
  );
}

/**
 * Whether a file's first bytes hold a zero byte, as a binary file's do.
 * @param head the file's first bytes
 * @returns true for a binary file
 */
export function looksBinary(head: Uint8Array): boolean {
  return head.includes(0);
}

/** One file the check read: its path, its bytes and its tokens, or the exemption it took. */
export type FileReading =
  | {
      readonly path: string;
      readonly kind: "counted";
      readonly bytes: number;
      readonly tokens: number;
    }
  | { readonly path: string; readonly kind: "exempt"; readonly why: string };

/**
 * The line a file over the cap refuses with: the file, its count and how to
 * split it.
 * @param reading the file's count
 * @param cap the cap
 * @returns the line, indented two spaces
 */
function overLine(
  reading: Extract<FileReading, { readonly kind: "counted" }>,
  cap: number,
): string {
  return `  ${reading.path}: about ${String(reading.tokens)} tokens (${String(reading.bytes)} bytes over four), over the cap of ${String(cap)}; split it in a slice of its own: move one cohesive part, a group of functions, a type and its parsers, a section, into a file of its own beside it, keep each file under the cap, and commit the move before any other change to either`;
}

/** The check's report: its text, and whether every file it counted stands under the cap. */
export interface FileTokensReport {
  readonly text: string;
  readonly green: boolean;
}

/**
 * The check's report: one line on what it read, then a line for each file
 * over the cap.
 * @param readings the files read
 * @param cap the cap
 * @returns the text and whether every file stands under the cap
 */
export function fileTokensReport(readings: readonly FileReading[], cap: number): FileTokensReport {
  const counted = readings.flatMap((reading) => (reading.kind === "counted" ? [reading] : []));
  const over = counted.filter((reading) => reading.tokens > cap);
  const exempt = readings.length - counted.length;
  const head = `greenline check files: ${String(counted.length)} file${counted.length === 1 ? "" : "s"} against ${String(cap)} tokens, ${String(exempt)} exempt; ${over.length === 0 ? "each under the cap" : `${String(over.length)} over it`}`;
  return {
    text: [head, ...over.map((reading) => overLine(reading, cap)), ""].join("\n"),
    green: over.length === 0,
  };
}
